export function dashboardPage(token: string, nonce: string, respondEnabled = false): string {
  // The token is generated by the server, not derived from an attacker-controlled path.
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Warden • Live defense</title><style>
:root{font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:#111410;color:#151a12}*{box-sizing:border-box}
body{margin:0;min-height:100vh}header{background:#c8fb4b;padding:26px clamp(22px,4vw,70px);display:flex;justify-content:space-between;align-items:center;gap:20px}
h1{font-size:clamp(2rem,4vw,4.5rem);letter-spacing:-.07em;margin:0;line-height:1}header p{margin:6px 0 0;font-weight:650}main{max-width:1720px;margin:auto;padding:32px clamp(16px,3vw,48px)}
.top{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-bottom:20px}.metric{background:#c8fb4b;border-radius:22px;padding:20px 25px;font-size:2.6rem;font-weight:850}.metric span{display:block;font-size:.85rem;font-weight:750;text-transform:uppercase;letter-spacing:.12em}
.grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(320px,1fr);gap:20px}.card{background:#fff;border-radius:26px;padding:24px;margin-bottom:20px;box-shadow:0 12px 45px #0002;min-width:0}h2{font-size:1.25rem;letter-spacing:-.03em;margin:0 0 15px}.sub{color:#53604d}.row{border-top:1px solid #e8ece3;padding:15px 2px;display:grid;gap:8px}.line{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap}.chip{padding:6px 11px;border-radius:100px;font-weight:800;font-size:.76rem;text-transform:uppercase;background:#e8ebe4}.block,.denied{background:#ffccc3}.ask,.pending{background:#ffe6a6}.allow,.trusted,.approved{background:#dbf8aa}.sandbox{background:#c4e9ff}
.tag{font-size:.74rem;text-transform:uppercase;letter-spacing:.11em;font-weight:800}.path{overflow-wrap:anywhere;font-weight:740}.reason{color:#485246;overflow-wrap:anywhere}.meta{font-size:.81rem;color:#66715f}.chain{border-left:4px solid #c8fb4b;padding-left:10px;overflow-wrap:anywhere}.evidence{background:#f1f6e9;border-radius:12px;padding:10px;font-size:.83rem;overflow-wrap:anywhere}button{border:0;border-radius:12px;background:#151a12;color:#fff;font-weight:800;padding:10px 17px;cursor:pointer}button:hover{background:#3d5b15}button.deny{background:#a42c21}button:disabled{opacity:.5;cursor:not-allowed}.count{font-variant-numeric:tabular-nums;color:#ad291b;font-weight:800}header .live{font-weight:800;background:#151a12;color:#c8fb4b;padding:9px 15px;border-radius:100px}
@media(max-width:950px){.grid{grid-template-columns:1fr}.top{grid-template-columns:repeat(3,1fr)}}@media(max-width:540px){.top{grid-template-columns:1fr}.metric{font-size:2rem}}
</style></head><body><header><div><h1>WARDEN<span style="color:#477009">.</span></h1><p>Live trust &amp; decision intelligence</p></div><span class="live">● LIVE LOCAL</span></header>
<main><div class="top"><div class="metric"><span>Decisions</span><strong id="count-decisions">0</strong></div><div class="metric"><span>Untrusted sessions</span><strong id="count-untrusted">0</strong></div><div class="metric"><span>Awaiting approval</span><strong id="count-pending">0</strong></div></div>
<div class="grid"><section><div class="card"><h2>Decision stream</h2><div id="decisions" class="sub">Waiting for agent activity…</div></div></section><aside><div class="card"><h2>Human approval</h2><div id="approvals" class="sub">No actions awaiting review.</div></div><div class="card"><h2>Session trust</h2><div id="sessions" class="sub">No sessions yet.</div></div><div class="card"><h2>Incidents</h2><div id="incidents" class="sub">No incident reports yet.</div></div></aside></div></main>
<script nonce="${nonce}">
const token=${JSON.stringify(token)};const respondEnabled=${JSON.stringify(respondEnabled)};let snapshot={decisions:[],sessions:[],approvals:[],incidents:[]};
const el=id=>document.getElementById(id);const node=(tag,text,cls)=>{const x=document.createElement(tag);x.textContent=String(text??'');if(cls)x.className=cls;return x};
function row(parent){const x=node('div','','row');parent.append(x);return x}function line(parent,...children){const x=node('div','','line');x.append(...children);parent.append(x);return x}
function empty(parent,text){parent.replaceChildren(node('p',text,'sub'))}function label(text,kind){return node('span',text,'chip '+kind)}
function render(){el('count-decisions').textContent=snapshot.decisions.length;el('count-untrusted').textContent=snapshot.sessions.filter(s=>s.untrusted).length;el('count-pending').textContent=snapshot.approvals.length;
const decisions=el('decisions');decisions.replaceChildren();if(!snapshot.decisions.length)empty(decisions,'Waiting for agent activity…');
for(const d of snapshot.decisions){const r=row(decisions);line(r,node('span',d.source+' / '+d.sessionId,'tag'),label(d.verdict,d.verdict));r.append(node('div',d.tool+' → '+d.target,'path'),node('div',d.reason,'reason'));const m='p '+Number(d.probability).toFixed(2)+' · R '+Number(d.budget).toFixed(2)+' · '+d.backend+(d.latencyMs?' / '+d.latencyMs+'ms':'')+' · '+d.at;r.append(node('div',m,'meta'));if(Object.keys(d.questions||{}).length)r.append(node('div',Object.entries(d.questions).map(([key,value])=>key+' '+Number(value).toFixed(2)).join(' · '),'meta'));if(d.sandbox){const s=d.sandbox;r.append(node('div','Sandbox '+s.backend+' / '+s.verdict+' · read '+s.read.join(', ')+' · changed '+s.changed.join(', ')+' · network '+s.network.join(', ')+' · control '+s.control.join(', ')+' · canaries '+s.canaries,'evidence'))}}
const sessions=el('sessions');sessions.replaceChildren();if(!snapshot.sessions.length)empty(sessions,'No sessions yet.');
for(const s of snapshot.sessions){const r=row(sessions);line(r,node('span',s.source+' / '+s.id,'path'),label(s.untrusted?'UNTRUSTED':'TRUSTED',s.untrusted?'denied':'trusted'));if(s.originReason)r.append(node('div',s.originReason,'chain'));r.append(node('small','Risk budget '+Number(s.budget).toFixed(2),'meta'))}
const approvals=el('approvals');approvals.replaceChildren();if(!snapshot.approvals.length)empty(approvals,'No actions awaiting review.');
for(const a of snapshot.approvals){const r=row(approvals);line(r,node('span',a.sessionId+' · '+a.tool,'path'),label('PENDING','pending'));r.append(node('div',a.target,'reason'),node('div',a.reason,'reason'));const countdown=node('div','','count');countdown.dataset.expires=a.expiresAt;r.append(countdown);const controls=node('div','','line');for(const choice of ['approved','denied']){const b=node('button',choice==='approved'?'Allow':'Deny',choice==='denied'?'deny':'');b.onclick=async()=>{b.disabled=true;try{const response=await fetch('/api/approvals/'+encodeURIComponent(a.id),{method:'POST',headers:{'content-type':'application/json','x-warden-token':token},body:JSON.stringify({choice})});if(!response.ok)throw Error('Approval was not accepted');await refresh()}catch{b.disabled=false;alert('Approval unavailable or expired.')}};controls.append(b)}r.append(controls)}
const incidents=el('incidents');incidents.replaceChildren();if(!snapshot.incidents.length)empty(incidents,'No incidents yet.');for(const incident of snapshot.incidents){const r=row(incidents);r.append(node('strong',incident.sessionId||incident.name,'path'),node('small',incident.status,'meta'));if(incident.report){const link=node('button','View report','path');link.onclick=async()=>{const response=await fetch('/api/reports/'+encodeURIComponent(incident.report),{headers:{'x-warden-token':token}});if(!response.ok)return alert('Report unavailable');const blob=new Blob([await response.text()],{type:'text/plain'});const url=URL.createObjectURL(blob);window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000)};r.append(link)}const b=node('button','Respond');b.disabled=!respondEnabled||incident.status==='Closed';b.title=respondEnabled?'Run the configured responder':'Responder integration will be enabled after the branches merge';b.onclick=async()=>{if(!confirm('Respond to '+(incident.sessionId||incident.name)+'?'))return;b.disabled=true;try{const response=await fetch('/api/incidents/'+encodeURIComponent(incident.name)+'/respond',{method:'POST',headers:{'content-type':'application/json','x-warden-token':token},body:'{}'});if(!response.ok)throw Error('Responder unavailable');await refresh()}catch{alert('Responder unavailable');b.disabled=false}};r.append(b)}tick()}
function tick(){for(const x of document.querySelectorAll('[data-expires]'))x.textContent=Math.max(0,Math.ceil((Date.parse(x.dataset.expires)-Date.now())/1000))+'s to decide'}
async function refresh(){try{const response=await fetch('/api/state',{headers:{'x-warden-token':token},cache:'no-store'});if(!response.ok)throw Error('offline');snapshot=await response.json();render()}catch{el('count-pending').textContent='—'}}
refresh();setInterval(refresh,750);setInterval(tick,200);
</script></body></html>`;
}